fn numpy_greater_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    // Ensure the inputs have the same length
    assert_eq!(x1.len(), x2.len(), "Input vectors must have the same length");

    // Zip the two vectors together, compare each pair, and collect the boolean results.
    x1.into_iter()
      .zip(x2.into_iter())
      .map(|(a, b)| a >= b)
      .collect()
}

